#include <bits/stdc++.h>
using namespace std;

// Minimal JSON reader for an array of strings; UTF-8 bytes pass through unchanged.
static string in;
static size_t p = 0;

static void skipSpace() {
    while (p < in.size() && (in[p] == ' ' || in[p] == '\t' || in[p] == '\n' || in[p] == '\r')) p++;
}

static void putUtf8(string &s, unsigned cp) {
    if (cp < 0x80) s += char(cp);
    else if (cp < 0x800) s += char(0xC0 | cp >> 6), s += char(0x80 | (cp & 0x3F));
    else if (cp < 0x10000) s += char(0xE0 | cp >> 12), s += char(0x80 | (cp >> 6 & 0x3F)), s += char(0x80 | (cp & 0x3F));
    else s += char(0xF0 | cp >> 18), s += char(0x80 | (cp >> 12 & 0x3F)), s += char(0x80 | (cp >> 6 & 0x3F)), s += char(0x80 | (cp & 0x3F));
}

static unsigned hex4() {
    unsigned v = stoul(in.substr(p, 4), nullptr, 16);
    p += 4;
    return v;
}

static string readString() {
    string s;
    p++;  // opening quote
    while (in[p] != '"') {
        char c = in[p++];
        if (c != '\\') {
            s += c;
            continue;
        }
        char e = in[p++];
        switch (e) {
            case 'b': s += '\b'; break;
            case 'f': s += '\f'; break;
            case 'n': s += '\n'; break;
            case 'r': s += '\r'; break;
            case 't': s += '\t'; break;
            case 'u': {
                unsigned cp = hex4();
                // Combine a surrogate pair written as two \u escapes.
                if (cp >= 0xD800 && cp < 0xDC00 && in.compare(p, 2, "\\u") == 0) {
                    size_t save = p;
                    p += 2;
                    unsigned low = hex4();
                    if (low >= 0xDC00 && low < 0xE000) cp = 0x10000 + ((cp - 0xD800) << 10) + (low - 0xDC00);
                    else p = save;
                }
                putUtf8(s, cp);
                break;
            }
            default: s += e;  // \" \\ \/
        }
    }
    p++;  // closing quote
    return s;
}

// Same escaping as Python json.dumps(..., ensure_ascii=False).
static void writeString(string &out, const string &s) {
    out += '"';
    for (unsigned char c : s) {
        if (c == '"') out += "\\\"";
        else if (c == '\\') out += "\\\\";
        else if (c == '\b') out += "\\b";
        else if (c == '\f') out += "\\f";
        else if (c == '\n') out += "\\n";
        else if (c == '\r') out += "\\r";
        else if (c == '\t') out += "\\t";
        else if (c < 0x20) {
            char buf[8];
            snprintf(buf, sizeof buf, "\\u%04x", c);
            out += buf;
        } else out += char(c);
    }
    out += '"';
}

int main() {
    in.assign(istreambuf_iterator<char>(cin), istreambuf_iterator<char>());
    vector<string> lines;
    skipSpace();
    p++;  // '['
    skipSpace();
    while (in[p] != ']') {
        lines.push_back(readString());
        skipSpace();
        if (in[p] == ',') p++;
        skipSpace();
    }
    // Chapter number = chapters so far; section number restarts in every chapter.
    int chapter = 0, section = 0;
    vector<string> result;
    for (const string &line : lines) {
        if (line.rfind("# ", 0) == 0) {
            chapter++;
            section = 0;
            result.push_back(to_string(chapter) + ". " + line.substr(2));
        } else if (line.rfind("## ", 0) == 0) {
