}

import java.io.*;
import java.util.*;
import java.nio.charset.StandardCharsets;

public class Main {
    // Minimal JSON reader for an array of strings (Java strings are UTF-16, so escaped code units map directly).
    static String in;
    static int p = 0;

    static void skipSpace() {
        while (p < in.length() && " \t\n\r".indexOf(in.charAt(p)) >= 0) p++;
    }

    static String readString() {
        StringBuilder s = new StringBuilder();
        p++; // opening quote
        while (in.charAt(p) != '"') {
            char c = in.charAt(p++);
            if (c != '\\') {
                s.append(c);
                continue;
            }
            char e = in.charAt(p++);
            switch (e) {
                case 'b' -> s.append('\b');
                case 'f' -> s.append('\f');
                case 'n' -> s.append('\n');
                case 'r' -> s.append('\r');
                case 't' -> s.append('\t');
                case 'u' -> {
                    s.append((char) Integer.parseInt(in.substring(p, p + 4), 16));
                    p += 4;
                }
                default -> s.append(e); // \" \\ \/
            }
        }
        p++; // closing quote
        return s.toString();
    }

    // Same escaping as Python json.dumps(..., ensure_ascii=False).
    static void writeString(StringBuilder out, String s) {
        out.append('"');
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"' -> out.append("\\\"");
                case '\\' -> out.append("\\\\");
                case '\b' -> out.append("\\b");
                case '\f' -> out.append("\\f");
                case '\n' -> out.append("\\n");
                case '\r' -> out.append("\\r");
                case '\t' -> out.append("\\t");
                default -> {
                    if (c < 0x20) out.append(String.format("\\u%04x", (int) c));
                    else out.append(c);
                }
            }
        }
        out.append('"');
    }

    public static void main(String[] args) throws IOException {
        in = new String(System.in.readAllBytes(), StandardCharsets.UTF_8);
        List<String> lines = new ArrayList<>();
        skipSpace();
        p++; // '['
        skipSpace();
        while (in.charAt(p) != ']') {
            lines.add(readString());
            skipSpace();
            if (in.charAt(p) == ',') p++;
            skipSpace();
        }
        // Chapter number = chapters so far; section number restarts in every chapter.
        int chapter = 0, section = 0;
        List<String> result = new ArrayList<>();
        for (String line : lines) {
            if (line.startsWith("# ")) {
                chapter++;
                section = 0;
                result.add(chapter + ". " + line.substring(2));
            } else if (line.startsWith("## ")) {
                section++;
                result.add(chapter + "." + section + ". " + line.substring(3));
            }
        }
        StringBuilder out = new StringBuilder("[");
        for (int i = 0; i < result.size(); i++) {
            if (i > 0) out.append(", ");
            writeString(out, result.get(i));
        }
        out.append("]\n");
        System.out.write(out.toString().getBytes(StandardCharsets.UTF_8));
        System.out.flush();
    }
}

package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"
)

// writeString escapes like Python json.dumps(..., ensure_ascii=False).
func writeString(out []byte, s string) []byte {
	out = append(out, '"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '"':
			out = append(out, `\"`...)
		case '\\':
			out = append(out, `\\`...)
		case '\b':
			out = append(out, `\b`...)
		case '\f':
			out = append(out, `\f`...)
		case '\n':
			out = append(out, `\n`...)
		case '\r':
			out = append(out, `\r`...)
		case '\t':
			out = append(out, `\t`...)
		default:
			if c < 0x20 {
				out = fmt.Appendf(out, `\u%04x`, c)
			} else {
				out = append(out, c)
			}
		}
	}
	return append(out, '"')
}

func main() {
	raw, _ := io.ReadAll(os.Stdin)
	var lines []string
	if err := json.Unmarshal(raw, &lines); err != nil {
		panic(err)
	}
	// Chapter number = chapters so far; section number restarts in every chapter.
	chapter, section := 0, 0
	var result []string
	for _, line := range lines {
		if strings.HasPrefix(line, "# ") {
			chapter++
			section = 0
			result = append(result, fmt.Sprintf("%d. %s", chapter, line[2:]))
		} else if strings.HasPrefix(line, "## ") {
			section++
			result = append(result, fmt.Sprintf("%d.%d. %s", chapter, section, line[3:]))
		}
	}
	out := []byte{'['}
	for i, s := range result {
		if i > 0 {
			out = append(out, ", "...)
		}
		out = writeString(out, s)
	}
	out = append(out, "]\n"...)
	os.Stdout.Write(out)
}
